#include <iostream>
#include <limits>
#include <stdexcept>
#include <optional>
// Example using checked arithmetic (C++20 and later):
int main() {
  try {
    std::checked_integer<int> a = 2147483647; // Max int32
    std::checked_integer<int> b = 1;
    std::checked_integer<int> sum = a + b; // Throws exception if overflow
    std::cout << sum << std::endl;
  } catch (const std::overflow_error& e) {
    std::cerr << "Integer overflow occurred: " << e.what() << std::endl;
  }
  //Example with a runtime check:
  int x = 2147483647;
  int y = 2;
  if (x > INT_MAX - y) {
    std::cerr << "Potential overflow detected" << std::endl;
  } else {
    int z = x + y; 
    std::cout << "Sum: " << z << std::endl; //safe here
  }
  return 0;
}
